import {useEffect,useMemo,useRef} from 'react';
import {$getSelection,$isRangeSelection,$createParagraphNode,$createTextNode,$getRoot,FORMAT_TEXT_COMMAND,INDENT_CONTENT_COMMAND,OUTDENT_CONTENT_COMMAND,UNDO_COMMAND,REDO_COMMAND} from 'lexical';
import {HeadingNode,$createHeadingNode,type HeadingTagType} from '@lexical/rich-text';
import {$setBlocksType} from '@lexical/selection';
import {LexicalComposer} from '@lexical/react/LexicalComposer';
import {useLexicalComposerContext} from '@lexical/react/LexicalComposerContext';
import {RichTextPlugin} from '@lexical/react/LexicalRichTextPlugin';
import {ContentEditable} from '@lexical/react/LexicalContentEditable';
import {HistoryPlugin} from '@lexical/react/LexicalHistoryPlugin';
import {OnChangePlugin} from '@lexical/react/LexicalOnChangePlugin';
import {LexicalErrorBoundary} from '@lexical/react/LexicalErrorBoundary';
import type {Manuscript} from '../../domain/manuscript';
import {importManuscript,exportManuscript,type ParagraphIdentities} from './adapter';
function RestoreFocus(){const [editor]=useLexicalComposerContext();useEffect(()=>{const restore=()=>editor.focus();document.addEventListener('writingtool-restore-writing-focus',restore);return()=>document.removeEventListener('writingtool-restore-writing-focus',restore);},[editor]);return null;}
function Toolbar({identities}:{identities:ParagraphIdentities}){const [editor]=useLexicalComposerContext();useEffect(()=>{const format=(event:Event)=>{const value=(event as CustomEvent<string>).detail;if(value==='bold'||value==='italic')editor.dispatchCommand(FORMAT_TEXT_COMMAND,value);else if(value==='indent')editor.dispatchCommand(INDENT_CONTENT_COMMAND,undefined);else if(value==='outdent')editor.dispatchCommand(OUTDENT_CONTENT_COMMAND,undefined);else if(value==='undo')editor.dispatchCommand(UNDO_COMMAND,undefined);else if(value==='redo')editor.dispatchCommand(REDO_COMMAND,undefined);else if(value==='scene')editor.update(()=>{const p=$createParagraphNode().append($createTextNode('***')),selection=$getSelection();if($isRangeSelection(selection)){const block=selection.anchor.getNode().getTopLevelElement();if(block){block.insertAfter(p);p.selectEnd();return;}}$getRoot().append(p);p.selectEnd();});else if(value==='body'||/^h[1-6]$/.test(value))editor.update(()=>{const selection=$getSelection();if($isRangeSelection(selection))$setBlocksType(selection,()=>value==='body'?$createParagraphNode():$createHeadingNode(value as HeadingTagType),(previous,next)=>{const id=identities.get(`${previous.getKey()}:0`);if(id)identities.set(`${next.getKey()}:0`,id);next.setIndent(previous.getIndent());});});};document.addEventListener('writingtool-format',format);return()=>document.removeEventListener('writingtool-format',format);},[editor,identities]);return <div className="writing-toolbar" role="toolbar" aria-label="Manuscript formatting"><button type="button" onClick={()=>editor.dispatchCommand(FORMAT_TEXT_COMMAND,'bold')}><b>Bold</b> <kbd>Ctrl+B</kbd></button><button type="button" onClick={()=>editor.dispatchCommand(FORMAT_TEXT_COMMAND,'italic')}><i>Italic</i> <kbd>Ctrl+I</kbd></button><label className="compact">Paragraph style<select aria-label="Paragraph style" defaultValue="body" onChange={e=>{const tag=e.target.value;editor.update(()=>{const selection=$getSelection();if($isRangeSelection(selection))$setBlocksType(selection,()=>tag==='body'?$createParagraphNode():$createHeadingNode(tag as HeadingTagType),(previous,next)=>{const id=identities.get(`${previous.getKey()}:0`);if(id)identities.set(`${next.getKey()}:0`,id);next.setIndent(previous.getIndent());});});}}><option value="body">Body</option>{[1,2,3,4,5,6].map(n=><option key={n} value={`h${n}`}>Heading {n}</option>)}</select></label><button type="button" onClick={()=>editor.dispatchCommand(INDENT_CONTENT_COMMAND,undefined)}>Indent</button><button type="button" onClick={()=>editor.dispatchCommand(OUTDENT_CONTENT_COMMAND,undefined)}>Outdent</button><button type="button" onClick={()=>editor.update(()=>{const paragraph=$createParagraphNode().append($createTextNode('***')),selection=$getSelection();if($isRangeSelection(selection)){const block=selection.anchor.getNode().getTopLevelElement();if(block){block.insertAfter(paragraph);paragraph.selectEnd();return;}}$getRoot().append(paragraph);paragraph.selectEnd();})}>Scene break ***</button><button type="button" onClick={()=>editor.dispatchCommand(UNDO_COMMAND,undefined)}>Undo <kbd>Ctrl+Z</kbd></button><button type="button" onClick={()=>editor.dispatchCommand(REDO_COMMAND,undefined)}>Redo <kbd>Ctrl+Shift+Z</kbd></button></div>;}
export function ManuscriptEditor({chapterId,initial,onChange,onError,fontFamily,fontSize}:{chapterId:string;initial:Manuscript;onChange:(v:Manuscript)=>void;onError:(e:Error)=>void;fontFamily:string;fontSize:string}){const identities=useRef<ParagraphIdentities>(new Map());const change=useRef(onChange),failure=useRef(onError);change.current=onChange;failure.current=onError;const config=useMemo(()=>({namespace:`chapter-${chapterId}`,nodes:[HeadingNode],theme:{text:{bold:'manuscript-bold',italic:'manuscript-italic'}},onError:(e:Error)=>failure.current(e),editorState:()=>importManuscript(initial,identities.current)}),[chapterId]);const last=useRef(JSON.stringify(initial));return <LexicalComposer initialConfig={config}><RestoreFocus/><Toolbar identities={identities.current}/><div className="writing-paper" style={{fontFamily,fontSize:`${fontSize}px`}}><RichTextPlugin contentEditable={<ContentEditable className="manuscript" aria-label="Chapter manuscript" spellCheck/>} placeholder={null} ErrorBoundary={LexicalErrorBoundary}/></div><HistoryPlugin/><OnChangePlugin ignoreSelectionChange ignoreHistoryMergeTagChange={false} onChange={state=>{try{const next=state.read(()=>exportManuscript(identities.current)),serialized=JSON.stringify(next);if(serialized!==last.current){last.current=serialized;change.current(next);}}catch(e){failure.current(e instanceof Error?e:new Error('Unable to read manuscript formatting.'));}}}/></LexicalComposer>;}
