import {useEffect,useMemo,useRef,useState} from 'react';
import type {WorkspaceSnapshot} from '../../application/contracts/workspace';
import {visibleRecord,decisionResolved,type WorkspaceRecord,type WorkspaceRecordOf,type ViewData} from '../../domain/workspace';
import {elapsedPosition,compareDates,type DatePosition} from '../../domain/calendar';
import {recordsOf,currentCalendar,dateLabel,recordLabel} from './model';
import {Check} from './Fields';
export function Filters({snapshot:s,onChange}:{snapshot:WorkspaceSnapshot;onChange:(v:ViewData)=>void}){const view=recordsOf(s,'view')[0]?.data??{makers:[],categories:[]},makers=[...recordsOf(s,'character'),...recordsOf(s,'faction')];return <details className="visibility"><summary>Visibility {view.makers.length||view.categories.length?'— filters active':'— show all'}</summary><button onClick={()=>onChange({makers:[],categories:[]})}>Show all</button><fieldset><legend>Makers (OR)</legend><Check label="No maker" checked={view.makers.some(m=>m.kind==='none')} onChange={yes=>onChange({...view,makers:yes?[...view.makers,{kind:'none'}]:view.makers.filter(m=>m.kind!=='none')})}/>{makers.map(r=><Check key={r.id} label={`${r.recordType}: ${r.data.name}`} checked={view.makers.some(m=>m.kind!=='none'&&m.id===r.id)} onChange={yes=>onChange({...view,makers:yes?[...view.makers,{kind:r.recordType,id:r.id}]:view.makers.filter(m=>m.kind==='none'||m.id!==r.id)})}/>)}</fieldset><fieldset><legend>Categories (OR; AND with makers)</legend><Check label="Universe Events" checked={view.categories.some(c=>c.kind==='events')} onChange={yes=>onChange({...view,categories:yes?[...view.categories,{kind:'events'}]:view.categories.filter(c=>c.kind!=='events')})}/>{recordsOf(s,'decision-type').map(t=><Check key={t.id} label={t.data.name} checked={view.categories.some(c=>c.kind==='decision-type'&&c.id===t.id)} onChange={yes=>onChange({...view,categories:yes?[...view.categories,{kind:'decision-type',id:t.id}]:view.categories.filter(c=>c.kind!=='decision-type'||c.id!==t.id)})}/>)}</fieldset></details>;}
export type TimelineFocus={start:DatePosition;end:DatePosition|null};
export function chapterTimelineFocus(chapter:WorkspaceRecordOf<'chapter'>|null|undefined):TimelineFocus|null{const start=chapter?.data.start??chapter?.data.end;return start?{start,end:chapter?.data.start?chapter.data.end:null}:null;}
type Dated=WorkspaceRecordOf<'event'>|WorkspaceRecordOf<'decision'>;
export function Timeline({snapshot:s,universeName,open,focus,zoom,goTo,createAt}:{snapshot:WorkspaceSnapshot;universeName:string;open:(r:WorkspaceRecord)=>void;focus:TimelineFocus|null;zoom:number;goTo:(d:DatePosition)=>void;createAt?:(d:DatePosition)=>void}){
 const calendar=currentCalendar(s),viewport=useRef<HTMLDivElement>(null),view=recordsOf(s,'view')[0]?.data??{makers:[],categories:[]};const [unresolved,setUnresolved]=useState(false),[anchor,setAnchor]=useState<bigint|null>(null),[period,setPeriod]=useState<bigint|null>(null);const records=[...recordsOf(s,'event'),...recordsOf(s,'decision')];
 const groups=useMemo(()=>{if(!calendar)return[];const visible=records.filter(r=>visibleRecord(r,view)&&(!unresolved||r.recordType==='decision'&&!decisionResolved(r.data))).sort((a,b)=>compareDates(a.data.date,b.data.date,calendar)||(BigInt(a.data.order)<BigInt(b.data.order)?-1:BigInt(a.data.order)>BigInt(b.data.order)?1:a.id.localeCompare(b.id)));const result:{position:bigint;date:DatePosition;records:Dated[]}[]=[];for(const r of visible){const position=elapsedPosition(r.data.date,calendar),last=result.at(-1);if(last?.position===position)last.records.push(r);else result.push({position,date:r.data.date,records:[r]});}return result;},[s,unresolved]);
 const zoomUnits=BigInt(Math.max(1,Math.round(zoom*1000))),base=period??365n,span=base*1000n/zoomUnits||1n,first=anchor??groups[0]?.position??0n,last=first+span;
 const shown=groups.filter(g=>g.position>=first&&g.position<=last);let pixelsPerDay=80n;for(let i=1;i<shown.length;i++){const gap=shown[i].position-shown[i-1].position,needed=BigInt(shown[i-1].records.length*34+50),scale=(needed+gap-1n)/gap;if(scale>pixelsPerDay)pixelsPerDay=scale;}const maxHeight=4_000_000n,desired=span*pixelsPerDay,height=Number(desired>maxHeight?maxHeight:desired<600n?600n:desired)+100;
 // Only view-relative bigint distances are converted to pixels; stored chronology stays exact.
 const y=(position:bigint)=>40+Number((position-first)*BigInt(height-100)/span);
 useEffect(()=>{if(!focus||!calendar)return;const a=elapsedPosition(focus.start,calendar),b=focus.end?elapsedPosition(focus.end,calendar):a,low=a<b?a:b,high=a>b?a:b;setAnchor(low);setPeriod(high>low?high-low+1n:31n);viewport.current?.scrollTo({top:0});},[focus,calendar?.currentVersion]);
 const jump=(date:DatePosition)=>{if(!calendar)return;setAnchor(elapsedPosition(date,calendar));setPeriod(31n);goTo(date);viewport.current?.scrollTo({top:0});};
 return <><p className="meta">Universe: {universeName}</p><Check label="Unresolved decisions only" checked={unresolved} onChange={setUnresolved}/>{unresolved&&<div className="unresolved-lookup" aria-label="Unresolved decisions">{records.filter((r):r is WorkspaceRecordOf<'decision'>=>r.recordType==='decision'&&!decisionResolved(r.data)&&visibleRecord(r,view)).map(d=><button className="context-record decision-code" key={d.id} onClick={()=>open(d)}>{d.data.code}: {d.data.text}<small>{dateLabel(d.data.date,calendar)} · {d.data.maker?[...recordsOf(s,'character'),...recordsOf(s,'faction')].find(m=>m.id===d.data.maker?.id)?.data.name??'Maker unavailable':'No maker'} · Unresolved</small></button>)}</div>}{!calendar?<p>Configure the universe calendar to plan dated records.</p>:<><div className="actions compact"><button onClick={()=>setAnchor(first-span)}>Earlier period</button><button onClick={()=>setAnchor(first+span)}>Later period</button><button disabled={!groups.length} onClick={()=>{setAnchor(groups[0].position);setPeriod(null);}}>First record</button><button disabled={!groups.length} onClick={()=>{setAnchor(groups.at(-1)!.position);setPeriod(31n);}}>Last record</button></div><p className="meta">Visible interval: {span.toString()} elapsed days. Zoom: {zoom}×.</p><label>Go to event or decision<select value="" onChange={e=>{const target=records.find(r=>r.id===e.target.value);if(target)jump(target.data.date);}}><option value="">Choose a canonical record</option>{records.map(r=><option key={r.id} value={r.id}>{r.data.code}: {recordLabel(r)}{visibleRecord(r,view)?'':' — Hidden by filters'}</option>)}</select></label>{!shown.length&&<p>{groups.length?'No matching records in this period. Use Earlier/Later or Go to a record.':records.length?'No records match these filters.':'No events or decisions yet.'}</p>}<div ref={viewport} className="timeline-scroll" aria-label="Vertical universe timeline"><div className="timeline-axis" style={{height}}>{shown.map(g=><div className="timeline-group" style={{top:y(g.position)}} key={g.position.toString()}><button className="timeline-date" onClick={()=>jump(g.date)}>{dateLabel(g.date,calendar)}</button><div className="timeline-codes">{createAt&&<button onClick={()=>createAt(g.date)}>New event here</button>}{g.records.map(r=><button className={r.recordType==='event'?'event-code':'decision-code'} title={`${r.recordType}: ${recordLabel(r)}`} aria-label={`${r.recordType} ${r.data.code}: ${recordLabel(r)}`} key={r.id} onClick={()=>open(r)}>{r.data.code} {r.recordType==='decision'?(decisionResolved(r.data)?'Resolved':'Unresolved'):'Event'}</button>)}</div></div>)}</div></div></>}</>;
}
export function DecisionTree({snapshot:s,open,selectedId,onFilters}:{snapshot:WorkspaceSnapshot;open:(r:WorkspaceRecord)=>void;selectedId?:string|null;onFilters?:(v:ViewData)=>void}){const decisions=recordsOf(s,'decision'),events=recordsOf(s,'event'),view=recordsOf(s,'view')[0]?.data??{makers:[],categories:[]};const candidates:Dated[]=[...decisions,...events.filter(e=>decisions.some(d=>d.data.eventIds.includes(e.id)))];const visibleIds=new Set(candidates.filter(n=>visibleRecord(n,view)).map(n=>n.id)),included=new Set(visibleIds);for(const d of decisions)for(const id of [...d.data.eventIds,...d.data.followingDecisionIds])if(visibleIds.has(d.id)||visibleIds.has(id)){included.add(d.id);included.add(id);}const nodes=candidates.filter(n=>included.has(n.id));const ranks=new Map<string,number>(),incoming=new Map(candidates.map(n=>[n.id,0]));for(const d of decisions)for(const id of [...d.data.followingDecisionIds,...d.data.eventIds])incoming.set(id,(incoming.get(id)??0)+1);const queue=candidates.filter(n=>incoming.get(n.id)===0).map(n=>n.id),byId=new Map(candidates.map(n=>[n.id,n]));for(let cursor=0;cursor<queue.length;cursor++){const id=queue[cursor],node=byId.get(id);if(node?.recordType!=='decision')continue;for(const target of [...node.data.followingDecisionIds,...node.data.eventIds]){ranks.set(target,Math.max(ranks.get(target)??0,(ranks.get(id)??0)+1));const count=(incoming.get(target)??1)-1;incoming.set(target,count);if(count===0)queue.push(target);}}const columns=new Map<number,Dated[]>();nodes.forEach(n=>{const k=ranks.get(n.id)??0;columns.set(k,[...columns.get(k)??[],n]);});const positions=new Map<string,{x:number;y:number}>();for(const [column,rows]of columns)rows.forEach((r,i)=>positions.set(r.id,{x:column*340+24,y:i*180+24}));const width=(Math.max(0,...columns.keys())+1)*340+24,height=Math.max(200,...[...columns.values()].map(c=>c.length*180+24));return <><h2>Established decision tree</h2>{onFilters&&<Filters snapshot={s} onChange={onFilters}/>}<p>Arrows follow canonical result links. Resolution uses all outgoing links, including hidden endpoints.</p>{!decisions.length?<p>No decisions saved yet.</p>:<div className="tree-scroll"><div className="tree-canvas" style={{width,height}}><svg width={width} height={height} aria-hidden="true"><defs><marker id="result-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="currentColor"/></marker></defs>{decisions.flatMap(d=>[...d.data.followingDecisionIds,...d.data.eventIds].map(id=>{const a=positions.get(d.id),b=positions.get(id);return a&&b?<path key={`${d.id}-${id}`} d={`M${a.x+280},${a.y+65} C${a.x+310},${a.y+65} ${b.x-30},${b.y+65} ${b.x},${b.y+65}`} fill="none" stroke="currentColor" markerEnd="url(#result-arrow)"/>:null;}))}</svg>{nodes.map(r=>{const p=positions.get(r.id)!,visible=visibleRecord(r,view);return <button key={r.id} aria-pressed={selectedId===r.id} className={`tree-node ${r.recordType==='event'?'event-code':'decision-code'}`} style={{left:p.x,top:p.y}} onClick={()=>open(r)}><strong>{r.data.code} · {r.recordType}</strong><span>{visible?recordLabel(r):'Hidden by filters'}</span>{r.recordType==='decision'&&<small>{decisionResolved(r.data)?'Resolved':'Unresolved'}</small>}</button>;})}</div></div>}</>;}
