import {type CalendarData,type CalendarConfiguration,positiveInteger} from '../../domain/calendar';
import {Field,Check,Select} from './Fields';
import {uuid} from './model';
export function CalendarForm({value,onChange}:{value:CalendarData;onChange:(v:CalendarData)=>void}){const config=value.versions.find(v=>v.id===value.currentVersion)!;
 const update=(patch:Partial<CalendarConfiguration>)=>{const next={...config,...patch};let actual='';if(next.elements.length){if(next.elements.every(e=>positiveInteger(e.days)))actual=next.elements.reduce((n,e)=>n+BigInt(e.days),0n).toString();}else actual=next.daysOnly??'';next.actualDays=actual;onChange({...value,anchor:value.versions.length===1?{year:next.enteredYear,day:'1'}:value.anchor,versions:value.versions.map(c=>c.id===config.id?next:c)});};
 const move=(i:number,delta:number)=>{const rows=[...config.elements],j=i+delta;if(j<0||j>=rows.length)return;[rows[i],rows[j]]=[rows[j],rows[i]];update({elements:rows});};
 return <><p>Year numbers may be negative, zero or positive. Saving a revision preserves elapsed positions and earlier calendar configurations.</p><Field label="Year number" value={config.enteredYear} onChange={enteredYear=>update({enteredYear})}/><Field label="Target days per year" value={config.targetDays} onChange={targetDays=>update({targetDays})}/><Check label="Use ordered months and standalone days" checked={!!config.elements.length} onChange={yes=>update(yes?{daysOnly:null,elements:[{id:uuid(),kind:'month',name:'',days:'1'}]}:{daysOnly:config.actualDays,elements:[]})}/>{!config.elements.length&&<Field label="Days per year" value={config.daysOnly??''} onChange={daysOnly=>update({daysOnly})}/>}{config.elements.map((e,i)=><fieldset key={e.id}><legend>Element {i+1}</legend><Select label="Kind" value={e.kind} onChange={kind=>update({elements:config.elements.map(x=>x.id===e.id?{...x,kind:kind as 'month'|'standalone',days:kind==='standalone'?'1':x.days}:x)})}><option value="month">Month</option><option value="standalone">Standalone day</option></Select><Field label="Name (optional)" value={e.name} onChange={name=>update({elements:config.elements.map(x=>x.id===e.id?{...x,name}:x)})}/>{e.kind==='month'&&<Field label="Days" value={e.days} onChange={days=>update({elements:config.elements.map(x=>x.id===e.id?{...x,days}:x)})}/>}<div className="actions"><button type="button" disabled={i===0} onClick={()=>move(i,-1)}>Move up</button><button type="button" disabled={i===config.elements.length-1} onClick={()=>move(i,1)}>Move down</button><button type="button" onClick={()=>update({elements:config.elements.filter(x=>x.id!==e.id),daysOnly:config.elements.length===1?config.actualDays:null})}>Remove</button></div></fieldset>)}{!!config.elements.length&&<div className="actions"><button type="button" onClick={()=>update({elements:[...config.elements,{id:uuid(),kind:'month',name:'',days:'1'}]})}>Add month</button><button type="button" onClick={()=>update({elements:[...config.elements,{id:uuid(),kind:'standalone',name:'',days:'1'}]})}>Add standalone day</button></div>}<p className={config.actualDays&&config.actualDays===config.targetDays?'match':'mismatch'} role="status">Actual: {config.actualDays||'invalid'} days. {config.actualDays===config.targetDays?'Target matches.':'Target differs; Save sets target to the actual total.'}</p><fieldset><legend>Year names (optional)</legend>{config.yearNames.map((n,i)=><div key={i} className="field-row"><Field label="Year" value={n.year} onChange={year=>update({yearNames:config.yearNames.map((x,j)=>i===j?{...x,year}:x)})}/><Field label="Name" value={n.name} onChange={name=>update({yearNames:config.yearNames.map((x,j)=>i===j?{...x,name}:x)})}/><button type="button" onClick={()=>update({yearNames:config.yearNames.filter((_,j)=>j!==i)})}>Remove year name</button></div>)}<button type="button" onClick={()=>update({yearNames:[...config.yearNames,{year:'',name:''}]})}>Add year name</button></fieldset></>;
}
