import {useEffect,useState,type ReactNode} from 'react';
import type {WorkspaceRecord,ManagedImage} from '../../domain/workspace';
import type {WorkspaceSnapshot,AssetData} from '../../application/contracts/workspace';
import type {Paragraph} from '../../domain/manuscript';
import type {DatePosition} from '../../domain/calendar';
import {allRecords,currentCalendar,dateLabel,recordLabel} from './model';
export function SavedPreview({record,text,snapshot,assets=[],historical=false}:{record:WorkspaceRecord|null;text:string|null;snapshot:WorkspaceSnapshot;assets?:AssetData[];historical?:boolean}){
 if(!record)return <p>No saved record</p>;const references=allRecords(snapshot),calendar=currentCalendar(snapshot),images=record.recordType==='character'?[record.data.image]:record.recordType==='faction'?[record.data.image,record.data.leaderImage]:[];
 const view=(value:unknown):ReactNode=>{if(value===null)return 'Not set';if(typeof value==='string'){const named=references.find(r=>r.id===value);if(named)return recordLabel(named);if(/^[a-f0-9-]{36}$/.test(value)){const configuration=calendar?.versions.find(v=>v.id===value);return configuration?`Calendar configuration (${configuration.id===calendar?.currentVersion?'current':'historical'})`:'Referenced item unavailable';}return value;}if(typeof value!=='object')return String(value);if('calendarVersion'in value&&'year'in value&&'day'in value)return dateLabel(value as DatePosition,calendar);if(Array.isArray(value))return value.length?<ul>{value.map((v,i)=><li key={i}>{view(v)}</li>)}</ul>:'None';return <dl>{Object.entries(value).filter(([field])=>!['formatting','image','leaderImage'].includes(field)).map(([field,v])=><div key={field}><dt>{field.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())}</dt><dd>{view(v)}</dd></div>)}</dl>;};
 return <><h4>{recordLabel(record)}</h4>{images.filter((i):i is ManagedImage=>!!i).map((image,index)=><SavedImage key={image.id+index} image={image} owner={snapshot.universe?.owner??record.owner} assets={assets} historical={historical}/>)}{view(record.data)}{record.recordType==='chapter'&&(text===null?<p>Captured manuscript is unavailable.</p>:<div className="saved-manuscript" aria-label={historical?'Captured manuscript formatting':'Current saved manuscript formatting'}>{record.data.formatting.paragraphs.map(p=><SavedParagraph key={p.id} paragraph={p} text={text}/>)}</div>)}</>;
}
function SavedParagraph({paragraph:p,text}:{paragraph:Paragraph;text:string}){const chars=Array.from(text),children:ReactNode[]=[];let at=Number(p.start);for(const mark of p.marks){children.push(chars.slice(at,Number(mark.start)).join(''));let run:ReactNode=chars.slice(Number(mark.start),Number(mark.end)).join('');if(mark.styles.includes('italic'))run=<em>{run}</em>;if(mark.styles.includes('bold'))run=<strong>{run}</strong>;children.push(<span key={mark.start}>{run}</span>);at=Number(mark.end);}children.push(chars.slice(at,Number(p.end)).join(''));return <div role={p.kind==='heading'?'heading':undefined} aria-level={p.kind==='heading'?p.headingLevel:undefined} className={`saved-paragraph saved-${p.kind}`} style={{paddingInlineStart:`${Number(p.indent)*4}ch`,whiteSpace:'pre-wrap',minHeight:'1.5em'}}>{children}</div>;}
function SavedImage({image,owner,assets,historical}:{image:ManagedImage;owner:WorkspaceRecord['owner'];assets:AssetData[];historical:boolean}){const [live,setLive]=useState<AssetData|null>(null);useEffect(()=>{let active=true;if(!historical)void window.writingTool.workspace({command:'workspace.asset.read',owner,assetId:image.id}).then(result=>{if(active&&result.status==='ok')setLive(result.asset);});return()=>{active=false;};},[historical,image.id,image.sha256,owner.id]);const bytes=historical?assets.find(asset=>asset.id===image.id&&asset.sha256===image.sha256&&asset.mediaType===image.mediaType):live;return bytes?<img className="profile-image" style={{objectFit:'contain'}} src={`data:${bytes.mediaType};base64,${bytes.base64}`} alt={historical?'Captured profile image':'Current saved profile image'}/>:<p>{historical?'Captured image unavailable; no live replacement was substituted.':'Current saved image unavailable.'}</p>;}
