import type {AppSettings,PanelLayout} from '../../application/contracts/workspace';
import {Field,Select,Check} from './Fields';
export const DEFAULT_PANELS:PanelLayout[]=['navigation','timeline','context'].map((id,i)=>({id,visible:true,collapsed:false,placement:i===2?'right':'left',order:String(i),width:i===2?'280':'250',height:'500',monitor:null,x:'80',y:'80'}));
export function SettingsForm({value,onChange,fonts,importSettings,exportSettings,selectBackup}:{value:AppSettings;onChange:(s:AppSettings)=>void;fonts:string[];importSettings:()=>void;exportSettings:()=>void;selectBackup:()=>void}){return <><h2>Settings</h2><fieldset><legend>Saving and protection</legend><Field label="Autosave interval (positive whole minutes)" value={value.autosaveMinutes} onChange={autosaveMinutes=>onChange({...value,autosaveMinutes})}/><Field label="Revision interval (positive whole minutes)" value={value.revisionMinutes} onChange={revisionMinutes=>onChange({...value,revisionMinutes})}/><Field label="Backup interval (positive whole minutes)" value={value.backupMinutes} onChange={backupMinutes=>onChange({...value,backupMinutes})}/><Field label="Retention (positive whole days)" value={value.retentionDays} onChange={retentionDays=>onChange({...value,retentionDays})}/><p>Backup destination: {value.backupDestination??'Not selected'}</p><button type="button" onClick={selectBackup}>Choose backup folder…</button></fieldset><fieldset><legend>Appearance and writing display</legend><Select label="Theme" value={value.theme} onChange={theme=>onChange({...value,theme:theme as AppSettings['theme']})}><option value="dark">Dark</option><option value="light">Light</option><option value="system">System</option></Select><label>Writing font family<input list="writing-fonts" value={value.fontFamily} onChange={e=>onChange({...value,fontFamily:e.target.value})}/><datalist id="writing-fonts"><option value="system-ui, sans-serif"/>{fonts.map(font=><option key={font} value={font}/>)}</datalist></label><p>Fonts change writing display only. Unavailable families use the system fallback.</p><Field label="Writing font size (px)" value={value.fontSize} onChange={fontSize=>onChange({...value,fontSize})}/></fieldset><fieldset><legend>App-wide panel layout</legend>{(value.panels.length?value.panels:DEFAULT_PANELS).map(panel=><fieldset key={panel.id}><legend>{panel.id}</legend><Check label="Visible" checked={panel.visible} onChange={visible=>onChange({...value,panels:(value.panels.length?value.panels:DEFAULT_PANELS).map(p=>p.id===panel.id?{...p,visible}:p)})}/><Select label="Placement" value={panel.placement} onChange={placement=>onChange({...value,panels:(value.panels.length?value.panels:DEFAULT_PANELS).map(p=>p.id===panel.id?{...p,placement:placement as PanelLayout['placement']}:p)})}>{['left','right','bottom','center','floating'].map(p=><option key={p} value={p}>{p}</option>)}</Select><Field label="Width" value={panel.width} onChange={width=>onChange({...value,panels:(value.panels.length?value.panels:DEFAULT_PANELS).map(p=>p.id===panel.id?{...p,width}:p)})}/><Field label="Height" value={panel.height} onChange={height=>onChange({...value,panels:(value.panels.length?value.panels:DEFAULT_PANELS).map(p=>p.id===panel.id?{...p,height}:p)})}/></fieldset>)}</fieldset><div className="actions"><button type="button" onClick={importSettings}>Import settings…</button><button type="button" onClick={exportSettings}>Export saved settings…</button></div></>;}
