import {createPortal} from 'react-dom';
import {useEffect,useRef,type ReactNode} from 'react';
export function Dialog({title,children,onCancel}:{title:string;children:ReactNode;onCancel:()=>void}){const ref=useRef<HTMLElement>(null),cancel=useRef(onCancel);cancel.current=onCancel;useEffect(()=>{const previous=document.activeElement as HTMLElement|null,root=ref.current!;const items=()=>Array.from(root.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]'));(root.querySelector<HTMLElement>('[autofocus]')??items()[0])?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();cancel.current();}if(e.key==='Tab'){const list=items(),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};root.addEventListener('keydown',key);return()=>{root.removeEventListener('keydown',key);if(previous?.isConnected)previous.focus();};},[]);return createPortal(<div className="scrim blocking"><section ref={ref} className="dialog" role="alertdialog" aria-modal="true" aria-label={title}><h2>{title}</h2>{children}</section></div>,document.body);}
