import {useEffect,useState} from 'react';
import {CHARACTER_PROMPTS,PERSONALITY_LABELS,characterCompleteness,factionCompleteness,affiliationHistory,visibleRecord,decisionResolved,type WorkspaceRecord,type ManagedImage,type Maker,type CharacterField} from '../../domain/workspace';
