import type {ReactNode} from 'react';
import {type CalendarData,type DatePosition,configuration,convertDate,displayDate} from '../../domain/calendar';
export function Field({label,value,onChange,multiline=false,optional=false}:{label:string;value:string;onChange:(v:string)=>void;multiline?:boolean;optional?:boolean}){return <label>{label}{optional&&<span className="optional"> (optional)</span>}{multiline?<textarea rows={4} value={value} onChange={e=>onChange(e.target.value)}/>:<input value={value} onChange={e=>onChange(e.target.value)}/>}</label>;}
export function Select({label,value,onChange,children}:{label:string;value:string;onChange:(v:string)=>void;children:ReactNode}){return <label>{label}<select value={value} onChange={e=>onChange(e.target.value)}>{children}</select></label>;}
export function Check({label,checked,onChange}:{label:string;checked:boolean;onChange:(v:boolean)=>void}){return <label className="check"><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/>{label}</label>;}
export function Choices({label,values,options,onChange}:{label:string;values:string[];options:{id:string;label:string}[];onChange:(v:string[])=>void}){return <fieldset className="choices"><legend>{label}</legend>{options.length?options.map(o=><Check key={o.id} label={o.label} checked={values.includes(o.id)} onChange={yes=>onChange(yes?[...values,o.id]:values.filter(v=>v!==o.id))}/>):<p>No saved choices yet.</p>}</fieldset>;}
export function DateField({label,value,calendar,onChange,required=false}:{label:string;value:DatePosition|null;calendar:CalendarData|null;onChange:(v:DatePosition|null)=>void;required?:boolean}){
 if(!calendar)return <p>{label}: Configure a calendar to enter dates.</p>;
 let current=value;try{if(current)current=convertDate(current,calendar);}catch{/* Preserve invalid values for feedback. */}
 const config=configuration(calendar,calendar.currentVersion);const set=(key:'year'|'day',text:string)=>onChange({...current??{calendarVersion:calendar.currentVersion,year:config.enteredYear,day:'1'},[key]:text});let labelText='';try{if(current)labelText=displayDate(current,calendar);}catch{labelText='Enter an integer year and a valid positive day of year.';}
 return <fieldset><legend>{label}{required?'':' (optional)'}</legend>{!required&&<Check label="Use a date" checked={!!current} onChange={yes=>onChange(yes?{calendarVersion:calendar.currentVersion,year:config.enteredYear,day:'1'}:null)}/>} {(current||required)&&<div className="field-row"><Field label="Year" value={current?.year??config.enteredYear} onChange={v=>set('year',v)}/><Field label={`Day of year (1–${config.actualDays})`} value={current?.day??'1'} onChange={v=>set('day',v)}/></div>}<p className="meta">{labelText}</p></fieldset>;
}
